const KEY='zhimoji_web_v2';
const UIKEY='zhimoji_web_ui_v1';
const empty=()=>({pens:[],inks:[],papers:[],fills:[],paperUsages:[],tests:[]});
let db=load();
let state={tab:'home',search:'',view:null,modal:null,recordFilter:'',randomType:'',randomResult:null,selector:null};
const NIB_SIZES=['EF','F','FM','MF','M','B','BB','C','MS'];
const NIB_MATERIALS=['钢','14K','18K','21K'];
const STORE_TYPES=['淘宝','京东','拼多多','闲鱼','小红书','快团团','实体店','其他'];
const PAPER_TAGS=['顺滑','不洇纸','不透背','不毛边','显 sheen','显浓淡','显色好','速干','笔迹收敛','细尖友好','双面可写','涂层匀','对金粉友好','色差小','触感好','洇纸','毛边','透背','挂纸','散墨','吸墨太快','起皱','泛黄','起毛','涂层脱落','色差大','掉粉','太厚','太薄','味道大','不显 sheen','裁切不齐','边缘粗糙'];
const INK_TAGS=['顺滑','流动性好','层析','变色','sheen','闪光','防水','耐光','速干','易清洗','不堵笔','不染尖','洇纸','透背','干速慢','堵笔','难清洗','染尖','沉淀','褪色','刺鼻'];
const PEN_TAGS=['顺滑','下水适中','软弹','手感好','重量舒服','气密性好','刮纸','飞白','漏墨','干尖','下水太大','下水太小','笔尖松','气密性差'];
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&typeof x==='object'?Object.assign(empty(),x):empty()}catch(e){return empty()}}
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function loadUI(){try{const x=JSON.parse(localStorage.getItem(UIKEY));return x&&typeof x==='object'?x:{}}catch(e){return {}}}
function saveUI(x){localStorage.setItem(UIKEY,JSON.stringify(x))}
function uid(p){return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function fmt(s){return s?String(s).replace(/-/g,'/'):''}
function penStatus(p){return p?.status==='retired'?'retired':p?.status==='idle'?'idle':'active'}
function usedInk(id){return db.fills.filter(f=>f.inkId===id).reduce((a,f)=>a+(+f.ml||0),0)}
function inkStatus(i){if(!i)return'active';if(i.statusManual==='empty')return'empty';if(i.statusManual==='active')return'active';const v=+i.volume||0;return v&&v-usedInk(i.id)-(+i.initialUsed||0)<=0?'empty':'active'}
function paperEmpty(p){const b=+p.buyQty||0;return b>0 && b-(+p.usedQty||0)<=0}
function openFillRecord(penId){return db.fills.find(f=>f.penId===penId&&!f.endDate)}
function inkName(id){const i=db.inks.find(x=>x.id===id);return i?(i.colorName||i.series||'未命名墨水'):'（已删除）'}
function penName(id){const p=db.pens.find(x=>x.id===id);return p?((p.brand||'')+' '+(p.model||'')).trim()||'未命名钢笔':'（已删除）'}
function paperName(id){const p=db.papers.find(x=>x.id===id);return p?((p.brand||'')+' '+(p.name||'')).trim()||'未命名纸张':'（已删除）'}
function swatch(i){if(!i)return'#ccc';const a=i.colorHex||'#ccc',b=i.colorHex2;if(i.gradientEnabled&&b&&b!==a)return`linear-gradient(135deg,${a},${b})`;return a}
function brandFill(b){let h=0;for(let i=0;i<String(b||'').length;i++)h=(h*31+String(b)[i].charCodeAt(0))%360;return`hsl(${h},22%,88%)`}
function brandBorder(b){let h=0;for(let i=0;i<String(b||'').length;i++)h=(h*31+String(b)[i].charCodeAt(0))%360;return`hsl(${h},28%,62%)`}
function layout(content){document.getElementById('app').innerHTML=`<div class="wrap"><header class="top"><h1>纸墨记</h1><div class="sub">我的钢笔、墨水与纸张记录</div></header><main class="content">${content}</main><nav class="nav">${[['home','⌂','首页'],['pen','✒','钢笔'],['ink','●','墨水'],['paper','▤','纸张'],['record','▤','记录'],['me','☷','我的']].map(x=>`<button class="${state.tab===x[0]?'active':''}" onclick="go('${x[0]}')"><b>${x[1]}</b>${x[2]}</button>`).join('')}</nav></div>`;renderModal()}
function go(tab){state={tab,search:'',view:null,modal:null,recordFilter:'',randomType:'',randomResult:null,selector:null};render()}
function render(){if(state.view?.type==='detail')return detail();if(state.view?.type==='form')return form();if(state.view?.type==='locations')return locationsPage();if(state.tab==='home')return home();if(state.tab==='pen')return listPage('pen','钢笔',db.pens,p=>penName(p.id));if(state.tab==='ink')return listPage('ink','墨水',db.inks,i=>i.colorName||i.series||'未命名墨水');if(state.tab==='paper')return listPage('paper','纸张',db.papers,p=>paperName(p.id));if(state.tab==='record')return recordPage();return me()}
function home(){const current=db.fills.filter(f=>!f.endDate);layout(`<div class="grid"><div class="card"><div class="stat">${db.pens.length}</div><div class="label">钢笔</div></div><div class="card"><div class="stat">${db.inks.length}</div><div class="label">墨水</div></div><div class="card"><div class="stat">${db.papers.length}</div><div class="label">纸张</div></div><div class="card"><div class="stat">${db.fills.length+db.paperUsages.length+db.tests.length}</div><div class="label">记录</div></div></div><div class="section-title">当前灌墨</div>${current.length?`<div class="list">${current.map(f=>`<div class="card row"><div class="swatch" style="background:${swatch(db.inks.find(i=>i.id===f.inkId))}"></div><div class="grow"><div class="name">${esc(penName(f.penId))}</div><div class="meta">${esc(inkName(f.inkId))} · ${fmt(f.date)}${f.ml?' · '+esc(f.ml)+' ml':''}</div></div><button class="ghost" onclick="openFill('${f.penId}')">换墨</button></div>`).join('')}</div>`:`<div class="card empty">还没有正在使用的墨水</div>`}<div class="section-title">快速入口</div><div class="quick-grid"><button class="quick" onclick="openRandomMenu()">🍀 随机笔墨</button><button class="quick" onclick="openRecordAdd()">＋ 记录一次</button><button class="quick" onclick="openTestForm()">✎ 书写测试</button><button class="quick" onclick="openLocations()">📍 位置</button></div>`)}
function listPage(type,title,items,label){const q=state.search.toLowerCase();const arr=items.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));layout(`<div class="bar"><input class="input" placeholder="搜索${title}" value="${esc(state.search)}" oninput="state.search=this.value;render()"><button class="primary" onclick="openForm('${type}')">＋</button></div><div class="list">${arr.length?arr.map(x=>itemCard(type,x,label)).join(''):`<div class="card empty">暂无${title}</div>`}</div>`)}
function itemCard(type,x,label){if(type==='ink')return`<div class="card row" onclick="openDetail('ink','${x.id}')"><div class="swatch" style="background:${swatch(x)}"></div><div class="grow"><div class="name">${esc(label(x))}</div><div class="meta">${esc([x.brand,x.series,x.volume?x.volume+' ml':'',inkStatus(x)==='empty'?'已空':''].filter(Boolean).join(' · '))}</div></div></div>`;return`<div class="card row" onclick="openDetail('${type}','${x.id}')"><div class="grow"><div class="name">${esc(label(x))}</div><div class="meta">${esc(type==='pen'?[x.nib,x.nibMaterial,x.location].filter(Boolean).join(' · '):[x.spec,x.style,x.weight?x.weight+' g':'',x.location].filter(Boolean).join(' · '))}</div></div></div>`}
function openDetail(type,id){state.view={type:'detail',itemType:type,id};render()}
function detail(){const type=state.view.itemType,id=state.view.id;const key=type==='pen'?'pens':type==='ink'?'inks':'papers';const x=db[key].find(v=>v.id===id);if(!x)return go(type);let body='';if(type==='pen'){const f=openFillRecord(id);body=`<div class="card"><div class="name">${esc(penName(id))}</div><div class="meta">${esc([x.nib,x.nibMaterial,x.madeYear?x.madeYear+'年':'',x.location].filter(Boolean).join(' · '))}</div>${f?`<div class="section-title">当前墨水</div><div class="row"><div class="swatch" style="background:${swatch(db.inks.find(i=>i.id===f.inkId))}"></div><div class="grow"><div class="name">${esc(inkName(f.inkId))}</div><div class="meta">${fmt(f.date)} · ${f.ml||''} ml</div></div></div>`:`<div class="meta">当前没有灌墨</div>`}</div><div class="actions"><button class="primary" onclick="openFill('${id}')">灌墨 / 换墨</button><button class="ghost" onclick="openForm('pen','${id}')">编辑</button></div><div class="section-title">灌墨历史</div><div class="list">${db.fills.filter(f=>f.penId===id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(f=>`<div class="card row"><div class="swatch" style="background:${swatch(db.inks.find(i=>i.id===f.inkId))}"></div><div class="grow"><div class="name">${esc(inkName(f.inkId))}</div><div class="meta">${fmt(f.date)} → ${fmt(f.endDate)||'现在'} · ${f.ml||''} ml</div></div></div>`).join('')}</div>`}else if(type==='ink'){const used=usedInk(id),remain=(+x.volume||0)-used-(+x.initialUsed||0);body=`<div class="card"><div class="row"><div class="swatch" style="background:${swatch(x)}"></div><div><div class="name">${esc(x.colorName||x.series||'未命名墨水')}</div><div class="meta">${esc([x.brand,x.series,x.year].filter(Boolean).join(' · '))}</div></div></div><div class="section-title">使用情况</div><div class="meta">容量 ${x.volume||'—'} ml · 已记录使用 ${used} ml · 初始已用 ${x.initialUsed||0} ml · 剩余约 ${Math.max(remain,0).toFixed(1)} ml</div>${x.tags?.length?`<div class="section-title">特性</div>${x.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}`:''}</div><div class="actions"><button class="ghost" onclick="openForm('ink','${id}')">编辑</button></div>`}else body=`<div class="card"><div class="name">${esc(paperName(id))}</div><div class="meta">${esc([x.style,x.spec,x.weight?x.weight+' g':'',x.location].filter(Boolean).join(' · '))}</div><div class="section-title">数量</div><div class="meta">购入 ${x.buyQty||0} · 已用 ${x.usedQty||0} · 剩余 ${(x.buyQty||0)-(x.usedQty||0)}</div></div><div class="actions"><button class="ghost" onclick="openForm('paper','${id}')">编辑</button></div>`;layout(`<button class="back" onclick="go('${type}')">‹ 返回${type==='pen'?'钢笔':type==='ink'?'墨水':'纸张'}</button><h2>${type==='pen'?'钢笔详情':type==='ink'?'墨水详情':'纸张详情'}</h2>${body}`)}
function openForm(type,id='',presetPen=''){state.view={type:'form',formType:type,id,presetPen};render()}
function openFill(penId=''){const f=penId?openFillRecord(penId):null;state.view={type:'form',formType:'fill',id:f?.id||'',presetPen:penId};render()}
function openTestForm(id=''){state.view={type:'form',formType:'test',id};render()}
function openUsageForm(id=''){state.view={type:'form',formType:'usage',id};render()}
function openRecordAdd(){state.modal='recordAdd';renderModal();}
function openLocations(){state.view={type:'locations'};render()}
function field(label,name,value='',type='text',extra=''){if(type==='textarea')return`<div class="field"><label>${label}</label><textarea class="textarea" name="${name}">${esc(value)}</textarea></div>`;return`<div class="field"><label>${label}</label><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function choiceField(label,name,value,list,emptyText='请选择'){return`<div class="field"><label>${label}</label><button type="button" class="picker-input" onclick="openChoice('${name}')">${esc(value||emptyText)} <span>›</span></button></div>`}
function form(){const t=state.view.formType,id=state.view.id;let obj={};if(['pen','ink','paper'].includes(t))obj=db[t==='pen'?'pens':t==='ink'?'inks':'papers'].find(x=>x.id===id)||{};if(t==='fill')obj=db.fills.find(x=>x.id===id)||{penId:state.view.presetPen||'',inkId:db.inks.find(i=>inkStatus(i)!=='empty')?.id||'',date:today(),ml:'',endDate:'',note:''};if(t==='usage')obj=db.paperUsages.find(x=>x.id===id)||{paperId:'',date:today(),qty:'',note:''};if(t==='test')obj=db.tests.find(x=>x.id===id)||{date:today(),dimension:'combo',penId:'',inkId:'',paperId:'',penIds:[],inkIds:[],paperIds:[],rating:0,note:'',review:'',paperTags:[],inkTags:[],penTags:[]};let html='';if(t==='pen'){const brands=getBrands(),locs=getLocations();html=`<div class="field"><label>品牌</label><div class="picker-line"><input class="input" name="brand" value="${esc(obj.brand||'')}"><button type="button" class="pick-btn" onclick="openChoice('brand')">选</button></div><div class="hint">已有品牌：${brands.slice(0,6).map(b=>`<button type="button" class="mini-chip" onclick="quickSet('brand',${JSON.stringify(b)})">${esc(b)}</button>`).join('')}</div></div>`+field('型号','model',obj.model)+`<div class="field"><label>笔尖</label><div class="picker-line"><input class="input" name="nib" value="${esc(obj.nib||'')}"><button type="button" class="pick-btn" onclick="openChoice('nib')">选</button></div></div>`+`<div class="field"><label>笔尖材质</label><div class="picker-line"><input class="input" name="nibMaterial" value="${esc(obj.nibMaterial||'')}"><button type="button" class="pick-btn" onclick="openChoice('nibMaterial')">选</button></div></div>`+field('生产年份','madeYear',obj.madeYear,'number')+`<div class="field"><label>位置</label><div class="picker-line"><input class="input" name="location" value="${esc(obj.location||'')}"><button type="button" class="pick-btn" onclick="openChoice('location')">选</button></div></div>`+field('购买日期','buyDate',obj.buyDate,'date')+`<div class="field"><label>购买渠道</label><select class="select" name="storeType">${STORE_TYPES.map(s=>`<option ${s===obj.storeType?'selected':''}>${s}</option>`).join('')}</select></div>`+field('店铺名','storeName',obj.storeName)+field('价格','price',obj.price,'number')+field('备注','note',obj.note,'textarea')+field('评价','review',obj.review,'textarea')+`<div class="field"><label>状态</label><select class="select" name="status"><option value="active" ${obj.status!=='idle'&&obj.status!=='retired'?'selected':''}>在用</option><option value="idle" ${obj.status==='idle'?'selected':''}>闲置</option><option value="retired" ${obj.status==='retired'?'selected':''}>退役</option></select></div>`}if(t==='ink')html=field('品牌','brand',obj.brand)+field('系列','series',obj.series)+field('颜色名','colorName',obj.colorName)+field('年份','year',obj.year,'number')+field('主色卡（HEX）','colorHex',obj.colorHex||'#CFCFCF')+field('副色卡（HEX，可留空）','colorHex2',obj.colorHex2)+`<div class="field"><label>双色渐变</label><select class="select" name="gradientEnabled"><option value="false" ${!obj.gradientEnabled?'selected':''}>否</option><option value="true" ${obj.gradientEnabled?'selected':''}>是</option></select></div>`+field('容量（ml）','volume',obj.volume,'number')+field('初始已用（ml）','initialUsed',obj.initialUsed,'number')+field('位置','location',obj.location)+field('购买日期','buyDate',obj.buyDate,'date')+field('价格','price',obj.price,'number')+field('特性标签（用逗号分隔）','tagsText',(obj.tags||[]).join(','))+field('备注','note',obj.note,'textarea')+field('评价','review',obj.review,'textarea')+`<div class="field"><label>状态</label><select class="select" name="statusManual"><option value="" ${!obj.statusManual?'selected':''}>自动</option><option value="active" ${obj.statusManual==='active'?'selected':''}>手动标记有墨</option><option value="empty" ${obj.statusManual==='empty'?'selected':''}>手动标记空瓶</option></select></div>`;if(t==='paper')html=field('品牌','brand',obj.brand)+field('名称','name',obj.name)+field('款式','style',obj.style)+field('规格','spec',obj.spec)+field('克重（g）','weight',obj.weight,'number')+field('购入张数','buyQty',obj.buyQty,'number')+field('已用张数','usedQty',obj.usedQty,'number')+field('价格','price',obj.price,'number')+field('购入日期','buyDate',obj.buyDate,'date')+field('购入渠道','channel',obj.channel)+field('位置','location',obj.location)+field('备注','note',obj.note,'textarea');if(t==='fill')html=`<div class="field"><label>钢笔</label><select class="select" name="penId">${db.pens.filter(p=>penStatus(p)==='active'||p.id===obj.penId).map(p=>`<option value="${p.id}" ${p.id===obj.penId?'selected':''}>${esc(penName(p.id))}</option>`).join('')}</select></div><div class="field"><label>墨水</label><select class="select" name="inkId">${db.inks.filter(i=>inkStatus(i)!=='empty'||i.id===obj.inkId).map(i=>`<option value="${i.id}" ${i.id===obj.inkId?'selected':''}>${esc(inkName(i.id))}</option>`).join('')}</select></div>${field('日期','date',obj.date||today(),'date')}${field('灌墨量（ml）','ml',obj.ml,'number')}${field('结束日期','endDate',obj.endDate,'date')}${field('备注','note',obj.note,'textarea')}<div class="note">同一瓶墨水可以出现在很多条记录中；保存新灌墨时会结束这支钢笔原来的未结束记录。</div>`;if(t==='usage')html=`<div class="field"><label>纸张</label><div class="picker-line"><input class="input" name="paperId" id="usagePaper" value="${esc(obj.paperId||'')}" readonly><button type="button" class="pick-btn" onclick="openChoice('paperForUsage')">选</button></div></div>${field('日期','date',obj.date||today(),'date')}${field('使用张数','qty',obj.qty,'number')}${field('备注','note',obj.note,'textarea')}`;if(t==='test')html=testFormHtml(obj);layout(`<button class="back" onclick="go('${t==='fill'||t==='usage'||t==='test'?'record':t}')">‹ 返回</button><h2>${id?'编辑':'新增'}${t==='pen'?'钢笔':t==='ink'?'墨水':t==='paper'?'纸张':t==='fill'?'灌墨记录':t==='usage'?'用纸记录':'书写测试'}</h2><form class="form" onsubmit="submitForm(event)">${html}<div class="actions"><button class="primary" type="submit">保存</button><button class="ghost" type="button" onclick="go('${t==='fill'||t==='usage'||t==='test'?'record':t}')">取消</button></div>${id?`<button class="ghost danger" type="button" onclick="removeItem('${t}','${id}')">删除</button>`:''}</form>`)}
function testFormHtml(o){const names=(ids,type)=>ids.map(id=>type==='pen'?penName(id):type==='ink'?inkName(id):paperName(id)).join('、');const selectedPen=o.penId||'';const selectedInk=o.inkId||'';const selectedPaper=o.paperId||'';return`<div class="field"><label>评价对象</label><div class="chips">${[['paper','评纸'],['ink','评墨'],['pen','评笔'],['combo','综合']].map(([k,l])=>`<button type="button" class="chip ${o.dimension===k?'on':''}" onclick="setTestDim('${k}')">${l}</button>`).join('')}</div><input type="hidden" name="dimension" id="testDimension" value="${esc(o.dimension||'combo')}"></div><div class="field"><label>钢笔</label><div class="picker-line"><input class="input" id="testPenLabel" value="${esc(selectedPen?penName(selectedPen):names(o.penIds||[],'pen'))}" readonly><button type="button" class="pick-btn" onclick="openChoice('testPen')">选</button></div><input type="hidden" name="penId" id="testPenId" value="${esc(selectedPen)}"><input type="hidden" name="penIds" id="testPenIds" value="${esc((o.penIds||[]).join(','))}"></div><div class="field"><label>墨水</label><div class="picker-line"><input class="input" id="testInkLabel" value="${esc(selectedInk?inkName(selectedInk):names(o.inkIds||[],'ink'))}" readonly><button type="button" class="pick-btn" onclick="openChoice('testInk')">选</button></div><input type="hidden" name="inkId" id="testInkId" value="${esc(selectedInk)}"><input type="hidden" name="inkIds" id="testInkIds" value="${esc((o.inkIds||[]).join(','))}"></div><div class="field"><label>纸张</label><div class="picker-line"><input class="input" id="testPaperLabel" value="${esc(selectedPaper?paperName(selectedPaper):names(o.paperIds||[],'paper'))}" readonly><button type="button" class="pick-btn" onclick="openChoice('testPaper')">选</button></div><input type="hidden" name="paperId" id="testPaperId" value="${esc(selectedPaper)}"><input type="hidden" name="paperIds" id="testPaperIds" value="${esc((o.paperIds||[]).join(','))}"></div>${field('日期','date',o.date||today(),'date')}<div class="field"><label>综合评分</label><div class="stars-input">${[1,2,3,4,5].map(i=>`<button type="button" class="star ${i<=+o.rating?'on':''}" onclick="setTestRating(${i})">★</button>`).join('')}</div><input type="hidden" name="rating" id="testRating" value="${esc(o.rating||0)}"></div><div class="field"><label>纸表现</label><div class="chips">${PAPER_TAGS.map(x=>`<button type="button" class="chip ${(o.paperTags||[]).includes(x)?'on':''}" data-tag="paperTags" data-v="${esc(x)}" onclick="toggleTag(this)">${esc(x)}</button>`).join('')}</div></div><div class="field"><label>墨表现</label><div class="chips">${INK_TAGS.map(x=>`<button type="button" class="chip ${(o.inkTags||[]).includes(x)?'on':''}" data-tag="inkTags" data-v="${esc(x)}" onclick="toggleTag(this)">${esc(x)}</button>`).join('')}</div></div><div class="field"><label>笔手感</label><div class="chips">${PEN_TAGS.map(x=>`<button type="button" class="chip ${(o.penTags||[]).includes(x)?'on':''}" data-tag="penTags" data-v="${esc(x)}" onclick="toggleTag(this)">${esc(x)}</button>`).join('')}</div></div>${field('备注','note',o.note)}${field('书写感受','review',o.review,'textarea')}`}
function submitForm(e){e.preventDefault();const t=state.view.formType,id=state.view.id;const fd=new FormData(e.target);const o=Object.fromEntries(fd.entries());if(t==='ink'){o.gradientEnabled=o.gradientEnabled==='true';o.tags=(o.tagsText||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean);delete o.tagsText}if(t==='test'){o.rating=+o.rating||0;o.penIds=(o.penIds||'').split(',').filter(Boolean);o.inkIds=(o.inkIds||'').split(',').filter(Boolean);o.paperIds=(o.paperIds||'').split(',').filter(Boolean);o.paperTags=getHiddenTags('paperTags');o.inkTags=getHiddenTags('inkTags');o.penTags=getHiddenTags('penTags');o.dimension=o.dimension||'combo';if(o.dimension==='paper'&&!o.paperId)return alert('评纸需要选择纸张');if(o.dimension==='ink'&&!o.inkId)return alert('评墨需要选择墨水');if(o.dimension==='pen'&&!o.penId)return alert('评笔需要选择钢笔');if(o.dimension==='combo'&&!o.penId&&!o.inkId&&!o.paperId)return alert('综合测试至少选择一项')}if(t==='fill'){if(!o.penId||!o.inkId)return alert('请选择钢笔和墨水');if(id){const i=db.fills.findIndex(x=>x.id===id);db.fills[i]=Object.assign({},db.fills[i],o)}else{db.fills.forEach(f=>{if(f.penId===o.penId&&!f.endDate)f.endDate=o.date});db.fills.push(Object.assign({id:uid('fill'),createdAt:Date.now()},o))}}else if(t==='usage'){if(!o.paperId||+o.qty<=0)return alert('请选择纸张并填写使用张数');const old=id?db.paperUsages.find(x=>x.id===id):null;if(old){const p=db.papers.find(x=>x.id===old.paperId);if(p)p.usedQty=Math.max(0,(+p.usedQty||0)-(+old.qty||0));const np=db.papers.find(x=>x.id===o.paperId);if(np)np.usedQty=(+np.usedQty||0)+(+o.qty||0);const i=db.paperUsages.findIndex(x=>x.id===id);db.paperUsages[i]=Object.assign({},db.paperUsages[i],o)}else{db.paperUsages.push(Object.assign({id:uid('usage'),createdAt:Date.now()},o));const p=db.papers.find(x=>x.id===o.paperId);if(p)p.usedQty=(+p.usedQty||0)+(+o.qty||0)}}else{const arr=t==='pen'?db.pens:t==='ink'?db.inks:db.papers;if(t==='pen'&&o.brand){const same=arr.find(x=>String(x.brand||'').trim().toLowerCase()===String(o.brand).trim().toLowerCase());if(same)o.brand=same.brand}if(id){const i=arr.findIndex(x=>x.id===id);arr[i]=Object.assign({},arr[i],o)}else arr.push(Object.assign({id:uid(t),createdAt:Date.now()},o))}if(t==='test'){if(!db.tests)db.tests=[];if(id){const i=db.tests.findIndex(x=>x.id===id);db.tests[i]=Object.assign({},db.tests[i],o)}else db.tests.push(Object.assign({id:uid('test'),createdAt:Date.now()},o))}save();go(t==='fill'||t==='usage'||t==='test'?'record':t)}
function getHiddenTags(group){return Array.from(document.querySelectorAll(`[data-tag="${group}"]`)).filter(x=>x.classList.contains('on')).map(x=>x.dataset.v)}
function removeItem(t,id){if(!confirm('确定删除吗？'))return;if(t==='pen'){db.pens=db.pens.filter(x=>x.id!==id);db.fills=db.fills.filter(x=>x.penId!==id)}else if(t==='ink')db.inks=db.inks.filter(x=>x.id!==id);else if(t==='paper')db.papers=db.papers.filter(x=>x.id!==id);else if(t==='fill')db.fills=db.fills.filter(x=>x.id!==id);else if(t==='usage'){const old=db.paperUsages.find(x=>x.id===id);if(old){const p=db.papers.find(x=>x.id===old.paperId);if(p)p.usedQty=Math.max(0,(+p.usedQty||0)-(+old.qty||0))}db.paperUsages=db.paperUsages.filter(x=>x.id!==id)}else if(t==='test')db.tests=db.tests.filter(x=>x.id!==id);save();go(['fill','usage','test'].includes(t)?'record':t)}
function me(){
  const ui=loadUI(), cfg=ui.alertCfg||{on:true,inkPct:20,inkMl:10,paperQty:100};
  const penCost=db.pens.reduce((a,x)=>a+(+x.price||0),0), inkCost=db.inks.reduce((a,x)=>a+(+x.price||0),0), paperCost=db.papers.reduce((a,x)=>a+(+x.price||0),0);
  const lowInks=db.inks.filter(i=>{if(inkStatus(i)==='empty')return false;const v=+i.volume||0;if(!v||!cfg.on)return false;const r=Math.max(0,v-usedInk(i.id)-(+i.initialUsed||0));return (cfg.inkPct>0&&r/v*100<=cfg.inkPct)||(cfg.inkMl>0&&r<=cfg.inkMl)});
  const lowPapers=db.papers.filter(x=>{const r=(+x.buyQty||0)-(+x.usedQty||0);return cfg.on&&cfg.paperQty>0&&r>0&&r<=cfg.paperQty});
  const last=ui.lastBackupAt||0, days=last?Math.floor((Date.now()-last)/86400000):null;
  const backupText=!last?'从未导出过备份':`已 ${days} 天未导出备份`;
  const showStats=ui.showStats!==false, hideEmptyInks=ui.hideEmptyInks===true, hideEmptyPapers=ui.hideEmptyPapers===true;
  layout(`<div class="section-title">提醒</div><div class="card"><div class="row"><div class="grow"><div class="name">库存与备份提醒</div><div class="meta">${lowInks.length?`有 ${lowInks.length} 瓶墨水快用完 · `:''}${lowPapers.length?`有 ${lowPapers.length} 款纸快没了 · `:''}${backupText}</div></div><button class="ghost" onclick="openAlertSettings()">设置</button></div>${lowInks.length?`<div class="note" style="margin-top:10px">快用完的墨水：${lowInks.slice(0,5).map(i=>esc(i.colorName||i.series||'未命名')).join('、')}${lowInks.length>5?'……':''}</div>`:''}</div>
  <div class="section-title">备份与恢复</div><div class="card"><div class="row-card row"><div class="grow"><div class="name">导出 JSON 备份</div><div class="meta">保存全部钢笔、墨水、纸张、记录以及界面设置</div></div><button class="ghost" onclick="exportFullBackup()">导出</button></div><div class="row-card row" style="margin-top:8px"><div class="grow"><div class="name">导入 Web 备份</div><div class="meta">覆盖当前 Web 数据与设置</div></div><button class="ghost" onclick="document.getElementById('webBackupFile').click()">导入</button></div><input id="webBackupFile" type="file" accept=".json,.txt,application/json,text/plain" hidden onchange="importFullBackup(this.files[0])"><div class="row-card row" style="margin-top:8px"><div class="grow"><div class="name">从微信版迁移</div><div class="meta">读取原微信小程序“我的 → 导出备份”文件</div></div><button class="primary" onclick="document.getElementById('wxfile2').click()">选择</button></div><input id="wxfile2" type="file" accept=".txt,.json,application/json,text/plain" hidden onchange="importWxData2(this.files[0])"></div>
  <div class="section-title">统计</div><div class="grid"><div class="card"><div class="stat">${db.pens.length}</div><div class="label">钢笔 · ¥${penCost.toFixed(2)}</div></div><div class="card"><div class="stat">${db.inks.length}</div><div class="label">墨水 · ¥${inkCost.toFixed(2)}</div></div><div class="card"><div class="stat">${db.papers.length}</div><div class="label">纸张 · ¥${paperCost.toFixed(2)}</div></div><div class="card"><div class="stat">${db.fills.length}</div><div class="label">灌墨记录</div></div><div class="card"><div class="stat">${db.paperUsages.length}</div><div class="label">用纸记录</div></div><div class="card"><div class="stat">${db.tests.length}</div><div class="label">书写测试</div></div><div class="card"><div class="stat">¥${(penCost+inkCost+paperCost).toFixed(2)}</div><div class="label">总花费</div></div><div class="card"><div class="stat">${db.papers.reduce((a,x)=>a+(+x.buyQty||0),0)}</div><div class="label">购入纸张总数</div></div></div>
  <div class="section-title">界面</div><div class="card"><div class="row setting-row"><div class="grow"><div class="name">列表显示统计行</div><div class="meta">钢笔 / 墨水 / 纸张页顶部的合计</div></div><label class="toggle"><input type="checkbox" ${showStats?'checked':''} onchange="setUI('showStats',this.checked)"><span></span></label></div><div class="row setting-row"><div class="grow"><div class="name">隐藏空瓶</div><div class="meta">墨水列表中不显示已用完的墨</div></div><label class="toggle"><input type="checkbox" ${hideEmptyInks?'checked':''} onchange="setUI('hideEmptyInks',this.checked)"><span></span></label></div><div class="row setting-row"><div class="grow"><div class="name">隐藏用完的纸</div><div class="meta">纸张列表中不显示已用完的纸</div></div><label class="toggle"><input type="checkbox" ${hideEmptyPapers?'checked':''} onchange="setUI('hideEmptyPapers',this.checked)"><span></span></label></div><div class="row setting-row" onclick="openAlertSettings()"><div class="grow"><div class="name">预警阈值</div><div class="meta">${alertSummaryWeb(cfg)}</div></div><span>›</span></div></div>
  <div class="section-title">标签与选项</div><div class="card manage-grid"><button class="manage-item" onclick="openManage('brandPen')"><b>钢笔品牌</b><small>${getBrandsFor('pens').length} 个 · 改名/合并</small></button><button class="manage-item" onclick="openManage('brandInk')"><b>墨水品牌</b><small>${getBrandsFor('inks').length} 个 · 改名/合并</small></button><button class="manage-item" onclick="openManage('brandPaper')"><b>纸张品牌</b><small>${getBrandsFor('papers').length} 个 · 改名/合并</small></button><button class="manage-item" onclick="openManage('series')"><b>墨水系列</b><small>${getSeries().length} 个 · 改名/合并</small></button><button class="manage-item" onclick="openManage('model')"><b>钢笔型号</b><small>${getModels().length} 个 · 修改</small></button><button class="manage-item" onclick="openManage('inkTag')"><b>墨水特性标签</b><small>${getUsedTags('ink').length} 个</small></button><button class="manage-item" onclick="openManage('paperTag')"><b>纸表现标签</b><small>${getUsedTags('paper').length} 个</small></button><button class="manage-item" onclick="openManage('penTag')"><b>笔手感标签</b><small>${getUsedTags('pen').length} 个</small></button><button class="manage-item" onclick="openManage('nibSize')"><b>笔尖粗细</b><small>${getNibSizes().length} 个</small></button><button class="manage-item" onclick="openManage('nibMaterial')"><b>笔尖材质</b><small>${getNibMaterials().length} 个</small></button></div>
  <div class="section-title">位置</div><div class="card row"><div class="grow"><div class="name">位置管理</div><div class="meta">查看你已经使用过的位置以及其中的物品</div></div><button class="ghost" onclick="openLocations()">打开</button></div>
  <div class="section-title">导出</div><div class="card"><div class="row"><div class="grow"><div class="name">导出全部数据（TSV）</div><div class="meta">可用 Excel / Numbers 打开</div></div><button class="ghost" onclick="exportTSV()">导出</button></div></div>
  <div class="section-title">批量导入</div><div class="card"><div class="meta manage-tip">网页端不能像微信版一样直接从剪贴板识别 Excel，但可以把表格另存为 TSV 后导入。模板也可以直接下载。</div><div class="manage-grid"><button class="manage-item" onclick="downloadTemplate('pen')"><b>钢笔模板</b><small>下载 TSV</small></button><button class="manage-item" onclick="downloadTemplate('ink')"><b>墨水模板</b><small>下载 TSV</small></button><button class="manage-item" onclick="downloadTemplate('paper')"><b>纸张模板</b><small>下载 TSV</small></button></div><input id="tsvFile" type="file" accept=".tsv,.txt,text/tab-separated-values,text/plain" hidden onchange="importTSV(this.files[0])"><button class="primary full" onclick="document.getElementById('tsvFile').click()">导入 TSV</button></div>
  <div class="section-title">危险操作</div><div class="card"><div class="row"><div class="grow"><div class="name">重置设置</div><div class="meta">恢复界面开关、预警、标签候选列表等默认值，不删除钢笔/墨水/纸张/记录</div></div><button class="ghost" onclick="resetWebUI()">重置</button></div><div class="row" style="margin-top:10px"><div class="grow"><div class="name">清空全部数据</div><div class="meta">删除当前浏览器中的全部纸墨记数据，无法撤销</div></div><button class="ghost danger" onclick="clearWebData()">清空</button></div></div>`)
}
function alertSummaryWeb(a){if(!a.on)return'已关闭';const p=[];if(+a.inkPct>0)p.push('墨 ≤'+a.inkPct+'%');if(+a.inkMl>0)p.push('或 ≤'+a.inkMl+' ml');if(+a.paperQty>0)p.push('纸 ≤'+a.paperQty+' 张');return p.join(' · ')||'已开启（未设阈值）'}
function setUI(k,v){const u=loadUI();u[k]=v;saveUI(u);render()}
function openAlertSettings(){state.modal='alertSettings';renderModal()}
function saveAlertWeb(){const f=document.getElementById('alertFormWeb');const u=loadUI();u.alertCfg={on:f.on.checked,inkPct:+f.inkPct.value||0,inkMl:+f.inkMl.value||0,paperQty:+f.paperQty.value||0};saveUI(u);closeModal();render()}
function exportFullBackup(){const u=loadUI();u.lastBackupAt=Date.now();saveUI(u);const blob=new Blob([JSON.stringify({version:1,app:'zhimoji',exportedAt:new Date().toISOString(),data:db,ui:u},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='zhimoji-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);render()}
function importFullBackup(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x?.data)throw 0;if(!confirm('恢复备份会覆盖当前数据与界面设置，确定继续吗？'))return;db=Object.assign(empty(),x.data);save();if(x.ui)saveUI(x.ui);render();alert('恢复成功')}catch(e){alert('备份文件无法识别')}};r.readAsText(file)}
function importWxData2(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result.split(/\r?\n/).filter(l=>!l.trim().startsWith('#')).join('\n'));if(!x?.data)throw 0;if(!confirm('将覆盖当前 Web 数据，确定继续吗？'))return;db=Object.assign(empty(),x.data);save();if(x.ui)saveUI(x.ui);render();alert('微信版数据导入成功')}catch(e){alert('微信版备份无法识别')}};r.readAsText(file)}
function resetWebUI(){if(!confirm('恢复所有界面设置为默认？已录入的数据不会删除。'))return;saveUI({showStats:true,hideEmptyInks:false,hideEmptyPapers:false,dashCollapsed:true,alertCfg:{on:true,inkPct:20,inkMl:10,paperQty:100},brandSort:{pen:{},ink:{},paper:{}},inkFeatureTags:{added:[],hidden:[]},testTags:{paper:{added:[],hidden:[]},ink:{added:[],hidden:[]},pen:{added:[],hidden:[]}},nibSizeTags:{added:[],hidden:[]},nibMaterialTags:{added:[],hidden:[]},lastBackupAt:0});render()}
function clearWebData(){if(!confirm('真的要清空全部数据吗？建议先导出备份。'))return;if(!confirm('再次确认：钢笔、墨水、纸张和所有记录都会被删除。'))return;db=empty();save();render()}
function getSeries(){return [...new Set(db.inks.map(x=>String(x.series||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function getNibSizes(){return [...new Set(db.pens.map(x=>String(x.nib||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function getNibMaterials(){return [...new Set(db.pens.map(x=>String(x.nibMaterial||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function exportTSV(){const rows=[['# 钢笔'],['品牌','型号','笔尖','材质','生产年份','购买日期','购买渠道','店铺名','价格','位置','备注','评价'],...db.pens.map(p=>[p.brand,p.model,p.nib,p.nibMaterial,p.madeYear,p.buyDate,p.storeType,p.storeName,p.price,p.location,p.note,p.review]),[],['# 墨水'],['品牌','系列','年份','颜色名','色值','容量(ml)','价格','购买日期','位置','标签','备注','评价'],...db.inks.map(i=>[i.brand,i.series,i.year,i.colorName,i.colorHex,i.volume,i.price,i.buyDate,i.location,(i.tags||[]).join('、'),i.note,i.review]),[],['# 纸张'],['品牌','名称','款式','规格','克重(g)','购入张数','已用张数','价格','购入日期','购入渠道','位置','备注'],...db.papers.map(p=>[p.brand,p.name,p.style,p.spec,p.weight,p.buyQty,p.usedQty,p.price,p.buyDate,p.channel,p.location,p.note])];const text='\ufeff'+rows.map(r=>r.map(v=>String(v??'').replace(/\t|\r?\n/g,' ')).join('\t')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/tab-separated-values;charset=utf-8'}));a.download='zhimoji-export-'+today()+'.tsv';a.click()}
function downloadTemplate(type){const maps={pen:['品牌','型号','笔尖','材质','生产年份','购买日期','购买渠道','店铺名','价格','位置','备注','评价'],ink:['品牌','系列','年份','颜色名','色值','容量(ml)','价格','购买日期','位置','标签','备注','评价'],paper:['品牌','名称','款式','规格','克重(g)','购入张数','已用张数','价格','购入日期','购入渠道','位置','备注']};const text='\ufeff'+maps[type].join('\t')+'\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/tab-separated-values;charset=utf-8'}));a.download='zhimoji-'+type+'-template.tsv';a.click()}
function importTSV(file){if(!file)return;const r=new FileReader();r.onload=()=>{const lines=r.result.replace(/^\ufeff/,'').split(/\r?\n/).filter(Boolean);if(!lines.length)return;const head=lines[0].split('\t');let type=head.includes('型号')?'pen':head.includes('颜色名')?'ink':head.includes('购入张数')?'paper':null;if(!type){alert('无法识别模板类型');return}const rows=lines.slice(1).filter(x=>!x.startsWith('#')).map(x=>x.split('\t'));if(!confirm(`识别到 ${rows.length} 条${type==='pen'?'钢笔':type==='ink'?'墨水':'纸张'}，确定导入吗？`))return;const keys={pen:['brand','model','nib','nibMaterial','madeYear','buyDate','storeType','storeName','price','location','note','review'],ink:['brand','series','year','colorName','colorHex','volume','price','buyDate','location','tags','note','review'],paper:['brand','name','style','spec','weight','buyQty','usedQty','price','buyDate','channel','location','note']}[type];const arr=rows.map(a=>{const o={id:uid(type),};keys.forEach((k,i)=>o[k]=a[i]||'');if(type==='ink')o.tags=(o.tags||'').split(/[、,]/).filter(Boolean);return o});db[type==='pen'?'pens':type==='ink'?'inks':'papers'].push(...arr);save();render();alert('导入完成')};r.readAsText(file)}

function exportData(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='zhimoji-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function importData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x||typeof x!=='object')throw 0;db=Object.assign(empty(),x);save();alert('导入成功');render()}catch(e){alert('备份文件无法识别')}};r.readAsText(file)}
function importWxData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{let text=r.result;const lines=text.split(/\r?\n/).filter(x=>!x.trim().startsWith('#'));const x=JSON.parse(lines.join('\n'));if(!x?.data)throw 0;db=Object.assign(empty(),x.data);save();alert('微信版数据导入成功');render()}catch(e){alert('微信版备份无法识别，请使用原小程序“我的 → 导出备份”得到的文件')}};r.readAsText(file)}
function getBrandsFor(key){return [...new Set((db[key]||[]).map(x=>String(x.brand||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function getModels(){const m={};db.pens.forEach(p=>{const brand=String(p.brand||'').trim(),model=String(p.model||'').trim();if(!model)return;const k=(brand+'\u0000'+model).toLowerCase();if(!m[k])m[k]={brand,model,count:0};m[k].count++});return Object.values(m).sort((a,b)=>(a.brand+' '+a.model).localeCompare(b.brand+' '+b.model,'zh-CN'))}
function getUsedTags(kind){const key=kind==='ink'?'tags':kind==='paper'?'paperTags':'penTags';const source=kind==='ink'?db.inks:db.tests;const m={};source.forEach(x=>(x[key]||[]).forEach(t=>{t=String(t||'').trim();if(t)m[t]=(m[t]||0)+1}));return Object.entries(m).map(([name,count])=>({name,count})).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))}
function openManage(kind){state.modal='manage:'+kind;renderModal()}
function manageTitle(kind){return {brandPen:'钢笔品牌',brandInk:'墨水品牌',brandPaper:'纸张品牌',series:'墨水系列',model:'钢笔型号',inkTag:'墨水特性标签',paperTag:'纸表现标签',penTag:'笔手感标签',nibSize:'笔尖粗细',nibMaterial:'笔尖材质'}[kind]||'资料管理'}
function manageItems(kind){if(kind==='brandPen')return getBrandsFor('pens').map(name=>({name,count:db.pens.filter(x=>String(x.brand||'').trim()===name).length,extra:''}));if(kind==='brandInk')return getBrandsFor('inks').map(name=>({name,count:db.inks.filter(x=>String(x.brand||'').trim()===name).length,extra:''}));if(kind==='brandPaper')return getBrandsFor('papers').map(name=>({name,count:db.papers.filter(x=>String(x.brand||'').trim()===name).length,extra:''}));if(kind==='model')return getModels().map(x=>({name:x.model,count:x.count,extra:x.brand}));if(kind==='series')return getSeries().map(name=>({name,count:db.inks.filter(x=>String(x.series||'').trim()===name).length,extra:'墨水'}));if(kind==='nibSize')return getNibSizes().map(name=>({name,count:db.pens.filter(x=>String(x.nib||'').trim()===name).length,extra:'钢笔'}));if(kind==='nibMaterial')return getNibMaterials().map(name=>({name,count:db.pens.filter(x=>String(x.nibMaterial||'').trim()===name).length,extra:'钢笔'}));return getUsedTags(kind==='inkTag'?'ink':kind==='paperTag'?'paper':'pen').map(x=>({name:x.name,count:x.count,extra:''}))}
function manageModal(){const kind=state.modal.slice(7),items=manageItems(kind);return`<div class="modal-mask" onclick="closeModal()"></div><div class="sheet"><div class="sheet-head"><button onclick="closeModal()">取消</button><b>修改${manageTitle(kind)}</b><span></span></div><div class="meta manage-tip">修改后会同步更新已有记录；如果新名称已经存在，会合并到已有名称。</div><div class="manage-list">${items.length?items.map(it=>`<div class="manage-row"><div class="grow"><div class="name">${esc(it.name)}</div><div class="meta">${esc(it.extra||'')}${it.extra?' · ':''}${it.count} 条</div></div><button class="ghost" onclick="renameManaged('${kind}',${JSON.stringify(it.name)},${JSON.stringify(it.extra||'')})">修改</button></div>`).join(''):`<div class="empty">还没有可修改的项目</div>`}</div></div>`}
function renameManaged(kind,oldName,extra){const title=manageTitle(kind);const next=prompt('修改'+title+'\n\n原名称：'+oldName+'\n\n请输入新名称：',oldName);if(next===null)return;const name=String(next).trim();if(!name||name===oldName)return;if(kind.startsWith('brand')){const key=kind==='brandPen'?'pens':kind==='brandInk'?'inks':'papers';(db[key]||[]).forEach(x=>{if(String(x.brand||'').trim()===oldName)x.brand=name})}else if(kind==='model'){db.pens.forEach(x=>{if(String(x.brand||'').trim()===extra&&String(x.model||'').trim()===oldName)x.model=name})}else if(kind==='series'){db.inks.forEach(x=>{if(String(x.series||'').trim()===oldName)x.series=name})}else if(kind==='nibSize'){db.pens.forEach(x=>{if(String(x.nib||'').trim()===oldName)x.nib=name})}else if(kind==='nibMaterial'){db.pens.forEach(x=>{if(String(x.nibMaterial||'').trim()===oldName)x.nibMaterial=name})}else{const key=kind==='inkTag'?'ink':kind==='paperTag'?'paper':'pen';if(key==='ink')db.inks.forEach(x=>{x.tags=(x.tags||[]).map(t=>String(t).trim()===oldName?name:t)});const tk=key==='paper'?'paperTags':'penTags';db.tests.forEach(x=>{x[tk]=(x[tk]||[]).map(t=>String(t).trim()===oldName?name:t)})}save();render()}

function getBrands(){return [...new Set(db.pens.map(p=>(p.brand||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function getLocations(){return [...new Set([...db.pens,...db.inks,...db.papers].map(x=>String(x.location||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function locationTree(){const set=new Set();getLocations().forEach(s=>{const parts=s.split('/').filter(Boolean);for(let i=1;i<=parts.length;i++)set.add(parts.slice(0,i).join('/'))});return [...set].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function childrenLocations(parent=''){const prefix=parent?parent+'/':'';const set=locationTree();return set.filter(p=>p.startsWith(prefix)).map(p=>p.slice(prefix.length)).filter(x=>x&&!x.includes('/')).map(name=>{const path=prefix+name;return{name,path,hasChild:set.some(x=>x.startsWith(path+'/')),count:[...db.pens,...db.inks,...db.papers].filter(x=>String(x.location||'')===path||String(x.location||'').startsWith(path+'/')).length}})}
function locationsPage(){const roots=childrenLocations('');const expanded=state.locExpanded||{};layout(`<button class="back" onclick="go('record')">‹ 返回记录</button><div class="page-title-row"><h2>位置</h2><button class="ghost" onclick="openChoice('location')">选择/新建</button></div><div class="card loc-card">${roots.length?roots.map(r=>locationRow(r,0)).join(''):`<div class="empty">还没有位置。添加钢笔、墨水或纸张时可以直接选择/输入位置。</div>`}</div>`)}
function locationRow(x,depth){const open=!!(state.locExpanded&&state.locExpanded[x.path]);const children=x.hasChild?childrenLocations(x.path):[];const items=locationItems(x.path);return`<div class="loc-row" style="padding-left:${18+depth*24}px"><button class="loc-toggle" type="button" onclick="toggleLocation('${esc(x.path)}')">${x.hasChild?(open?'▾':'▸'):'•'}</button><button class="link" type="button" onclick="toggleLocation('${esc(x.path)}')">${esc(x.name)}</button><span class="loc-count">${x.count}</span></div>${open?`${items.length?`<div class="loc-items" style="margin-left:${42+depth*24}px">${items.map(i=>`<div class="loc-item"><span>${i.kind}</span><span class="grow">${esc(i.name)}</span></div>`).join('')}`:''}${children.map(c=>locationRow(c,depth+1)).join('')}`:''}`}
function locationItems(path){return[...db.pens.map(x=>({kind:'钢笔',name:penName(x.id),loc:x.location})),...db.inks.map(x=>({kind:'墨水',name:inkName(x.id),loc:x.location})),...db.papers.map(x=>({kind:'纸张',name:paperName(x.id),loc:x.location}))].filter(x=>x.loc===path)}
function toggleLocation(path){state.locExpanded=state.locExpanded||{};state.locExpanded[path]=!state.locExpanded[path];render()}
function showLocation(path){toggleLocation(path)}
function openChoice(type){state.modal='choice:'+type;renderModal()}
function quickSet(name,v){const el=document.querySelector(`[name="${name}"]`);if(el)el.value=v}
function choiceItems(type){if(type==='brand')return getBrands();if(type==='nib')return NIB_SIZES;if(type==='nibMaterial')return NIB_MATERIALS;if(type==='location')return locationTree();if(type==='paperForUsage')return db.papers.filter(p=>!paperEmpty(p)).map(p=>({id:p.id,name:paperName(p.id),sub:p.spec||''}));if(type==='testPen')return db.pens.map(p=>({id:p.id,name:penName(p.id),sub:p.nib||''}));if(type==='testInk')return db.inks.filter(i=>inkStatus(i)!=='empty').map(i=>({id:i.id,name:inkName(i.id),sub:[i.brand,i.series].filter(Boolean).join(' · '),sw:swatch(i)}));if(type==='testPaper')return db.papers.filter(p=>!paperEmpty(p)).map(p=>({id:p.id,name:paperName(p.id),sub:p.spec||''}));return[]}
function renderModal(){const host=document.getElementById('modal');if(!host)return;host.innerHTML='';if(state.modal?.startsWith('manage:')){host.innerHTML=manageModal();return}if(state.modal==='alertSettings'){const a=loadUI().alertCfg||{on:true,inkPct:20,inkMl:10,paperQty:100};host.innerHTML=`<div class="modal-mask" onclick="closeModal()"></div><div class="sheet"><div class="sheet-head"><button onclick="closeModal()">取消</button><b>预警阈值</b><span></span></div><form id="alertFormWeb" class="form"><div class="row"><div class="grow"><b>开启预警</b></div><label class="toggle"><input name="on" type="checkbox" ${a.on?'checked':''}><span></span></label></div><div class="field"><label>墨水剩余百分比 ≤</label><input class="input" name="inkPct" type="number" min="0" value="${a.inkPct}"></div><div class="field"><label>或墨水剩余容量 ≤ ml</label><input class="input" name="inkMl" type="number" min="0" value="${a.inkMl}"></div><div class="field"><label>纸张剩余 ≤ 张</label><input class="input" name="paperQty" type="number" min="0" value="${a.paperQty}"></div><div class="actions"><button class="primary" type="button" onclick="saveAlertWeb()">保存</button></div></form></div>`;return}if(state.modal==='recordAdd'){host.innerHTML=`<div class="modal-mask" onclick="closeModal()"></div><div class="sheet"><div class="sheet-head"><span></span><b>新增记录</b><button onclick="closeModal()">取消</button></div><button class="sheet-option" onclick="closeModal();openFill()">记录灌墨</button><button class="sheet-option" onclick="closeModal();openUsageForm()">记录用纸</button><button class="sheet-option" onclick="closeModal();openTestForm()">书写测试</button></div>`;return}if(state.modal==='random'){host.innerHTML=randomModal();return}if(state.modal?.startsWith('choice:')){const type=state.modal.slice(7);const items=choiceItems(type);host.innerHTML=`<div class="modal-mask" onclick="closeModal()"></div><div class="sheet selector"><div class="sheet-head"><button onclick="closeModal()">取消</button><b>${type==='brand'?'选择品牌':type==='location'?'选择位置':type==='nib'?'选择笔尖':type==='nibMaterial'?'选择笔尖材质':type==='paperForUsage'?'选择纸张':'选择'+(type==='testPen'?'钢笔':type==='testInk'?'墨水':'纸张')}</b><span></span></div><input class="input selector-search" placeholder="搜索..." oninput="filterChoice(this)"><div id="choiceList" class="choice-list">${choiceListHtml(type,items)}</div></div>`}}
function choiceArg(v){return esc(JSON.stringify(String(v??'')))}
function choiceListHtml(type,items){if(!items.length)return`<div class="empty">还没有可选项</div>`;return items.map(it=>{if(typeof it==='string')return`<button type="button" class="choice" onclick="chooseValue('${type}',${choiceArg(it)})"><span>${esc(it)}</span></button>`;return`<button type="button" class="choice" onclick="chooseValue('${type}',${choiceArg(it.id)})">${it.sw?`<span class="swatch" style="background:${it.sw}"></span>`:''}<span><b>${esc(it.name)}</b><small>${esc(it.sub||'')}</small></span></button>`}).join('')}
function filterChoice(input){const type=state.modal.slice(7),all=choiceItems(type),q=input.value.toLowerCase();const filtered=all.filter(it=>typeof it==='string'?it.toLowerCase().includes(q):(it.name||'').toLowerCase().includes(q)||(it.sub||'').toLowerCase().includes(q));document.getElementById('choiceList').innerHTML=choiceListHtml(type,filtered)}
function chooseValue(type,value){closeModal();if(type==='brand'||type==='nib'||type==='nibMaterial'||type==='location'){const el=document.querySelector(`[name="${type==='nib'?'nib':type}"]`);if(el)el.value=value;else if(type==='location'){const x=document.querySelector('[name="location"]');if(x)x.value=value}return}if(type==='paperForUsage'){const x=document.getElementById('usagePaper');if(x){x.value=value;const p=db.papers.find(p=>p.id===value);x.dataset.label=p?paperName(p.id):value}return}if(type.startsWith('test')){setTestChoice(type,value)}}
function closeModal(){state.modal=null;const h=document.getElementById('modal');if(h)h.innerHTML=''}
function setTestDim(k){const el=document.getElementById('testDimension');if(el)el.value=k;document.querySelectorAll('.chip').forEach(b=>{if(['评纸','评墨','评笔','综合'].includes(b.textContent))b.classList.toggle('on',b.textContent===({paper:'评纸',ink:'评墨',pen:'评笔',combo:'综合'}[k]))})}
function setTestRating(v){const el=document.getElementById('testRating');if(el)el.value=v;document.querySelectorAll('.star').forEach((b,i)=>b.classList.toggle('on',i<v))}
function toggleTag(el){el.classList.toggle('on')}
function setTestChoice(type,id){const map={testPen:['testPenId','testPenIds','testPenLabel','pen'],testInk:['testInkId','testInkIds','testInkLabel','ink'],testPaper:['testPaperId','testPaperIds','testPaperLabel','paper']};const [single,multi,label,kind]=map[type];const target=document.getElementById(single);const item=kind==='pen'?penName(id):kind==='ink'?inkName(id):paperName(id);if(target)target.value=id;const arrEl=document.getElementById(multi);if(arrEl)arrEl.value=id;if(document.getElementById(label))document.getElementById(label).value=item}
function openRandomMenu(){state.modal='random';state.randomType='pen';rollRandom('pen');renderModal()}
function randomPool(type){if(type==='pen')return db.pens.filter(p=>penStatus(p)!=='retired'&&!!openFillRecord(p.id));if(type==='ink')return db.inks.filter(i=>inkStatus(i)!=='empty');if(type==='paper')return db.papers.filter(p=>!paperEmpty(p));if(type==='combo'){const used=new Set(db.fills.filter(f=>!f.endDate).map(f=>f.inkId));return {pens:db.pens.filter(p=>penStatus(p)==='active'&&!openFillRecord(p.id)),inks:db.inks.filter(i=>inkStatus(i)!=='empty'&&!used.has(i.id))}}return[]}
function rollRandom(type){state.randomType=type;let result=null;if(type==='pen'){const a=randomPool('pen');const p=a[Math.floor(Math.random()*a.length)];if(p){const f=openFillRecord(p.id);result={type,pen:{id:p.id,name:penName(p.id),sub:[p.nibMaterial,p.nib,inkName(f?.inkId)].filter(Boolean).join(' · '),sw:f?swatch(db.inks.find(i=>i.id===f.inkId)):brandFill(p.brand)}}}}else if(type==='ink'){const a=randomPool('ink');const i=a[Math.floor(Math.random()*a.length)];if(i)result={type,ink:{id:i.id,name:inkName(i.id),sub:[i.brand,i.series].filter(Boolean).join(' · '),sw:swatch(i)}}}else if(type==='paper'){const a=randomPool('paper');const p=a[Math.floor(Math.random()*a.length)];if(p)result={type,paper:{id:p.id,name:paperName(p.id),sub:[p.spec,p.style,p.weight?p.weight+'g':''].filter(Boolean).join(' · '),sw:'#ddd'}}}else{const a=randomPool('combo');if(a.pens.length&&a.inks.length){const p=a.pens[Math.floor(Math.random()*a.pens.length)],i=a.inks[Math.floor(Math.random()*a.inks.length)];result={type,pen:{id:p.id,name:penName(p.id),sub:[p.nibMaterial,p.nib].filter(Boolean).join(' · '),sw:brandFill(p.brand)},ink:{id:i.id,name:inkName(i.id),sub:[i.brand,i.series].filter(Boolean).join(' · '),sw:swatch(i)}}}}state.randomResult=result;state.modal='random';renderModal()}
function randomModal(){const r=state.randomResult;return`<div class="modal-mask" onclick="closeModal()"></div><div class="sheet"><div class="sheet-head"><button onclick="closeModal()">取消</button><b>🍀 今日随选</b><span></span></div><div class="random-switch"><button onclick="rollRandom('pen')">灌墨中的笔</button><button onclick="rollRandom('ink')">在用墨</button><button onclick="rollRandom('paper')">在用纸</button><button onclick="rollRandom('combo')">笔＋墨</button></div>${r?`<div class="random-card">${r.pen?`<div class="row"><div class="swatch" style="background:${r.pen.sw}"></div><div class="grow"><div class="name">${esc(r.pen.name)}</div><div class="meta">${esc(r.pen.sub)}</div></div></div>`:''}${r.ink?`<div class="row divider"><div class="swatch" style="background:${r.ink.sw}"></div><div class="grow"><div class="name">${esc(r.ink.name)}</div><div class="meta">${esc(r.ink.sub)}</div></div></div>`:''}${r.paper?`<div class="row"><div class="swatch" style="background:${r.paper.sw}"></div><div class="grow"><div class="name">${esc(r.paper.name)}</div><div class="meta">${esc(r.paper.sub)}</div></div></div>`:''}</div>`:`<div class="empty">这个类别暂时没有可随机的项目</div>`}<div class="actions"><button class="ghost" onclick="rollRandom('${state.randomType}')">换一批</button>${r?`<button class="primary" onclick="acceptRandom()">${r.type==='combo'?'就它了 · 去灌墨':'就它了'}</button>`:''}</div></div>`}
function acceptRandom(){const r=state.randomResult;if(!r)return;if(r.type==='combo'){closeModal();openFill();setTimeout(()=>{const p=document.querySelector('[name="penId"]'),i=document.querySelector('[name="inkId"]');if(p)p.value=r.pen.id;if(i)i.value=r.ink.id},0)}else{closeModal();openDetail(r.type,r[r.type].id)}}
function recordPage(){const all=[];db.fills.forEach(f=>all.push({type:'fill',id:f.id,date:f.date,title:'灌墨 · '+inkName(f.inkId),sub:[penName(f.penId),f.ml?f.ml+' ml':'',f.endDate?'至 '+fmt(f.endDate):''].filter(Boolean).join(' · '),sw:swatch(db.inks.find(i=>i.id===f.inkId))}));(db.paperUsages||[]).forEach(u=>all.push({type:'usage',id:u.id,date:u.date,title:'用纸 · '+paperName(u.paperId),sub:[u.qty+' 张',u.note].filter(Boolean).join(' · '),sw:'#ddd'}));(db.tests||[]).forEach(t=>{const dim={paper:'评纸',ink:'评墨',pen:'评笔',combo:'综合'}[t.dimension]||'综合';const primary=t.dimension==='paper'?paperName(t.paperId):t.dimension==='ink'?inkName(t.inkId):t.dimension==='pen'?penName(t.penId):(inkName(t.inkId)!=='（已删除）'?inkName(t.inkId):paperName(t.paperId));all.push({type:'test',id:t.id,date:t.date,title:dim+' · '+primary,sub:[t.rating?'★'.repeat(+t.rating):'',t.note||t.review||''].filter(Boolean).join(' · '),sw:swatch(db.inks.find(i=>i.id===t.inkId))})});all.sort((a,b)=>(b.date||'').localeCompare(a.date||''));const arr=state.recordFilter?all.filter(x=>x.type===state.recordFilter):all;layout(`<div class="page-title-row"><div><h2>记录</h2><div class="meta">灌墨、用纸、书写测试都在这里</div></div><div class="head-actions"><button class="icon-btn" onclick="openRecordAdd()">＋</button></div></div><div class="filter-tabs">${[['','全部'],['fill','灌墨'],['usage','用纸'],['test','测试']].map(([k,l])=>`<button class="${state.recordFilter===k?'on':''}" onclick="state.recordFilter='${k}';render()">${l}</button>`).join('')}</div><div class="list">${arr.length?arr.map(r=>`<div class="card row" onclick="openRecordDetail('${r.type}','${r.id}')"><div class="swatch" style="background:${r.sw}"></div><div class="grow"><div class="name">${esc(r.title)}</div><div class="meta">${esc(r.sub)}${r.date?' · '+fmt(r.date):''}</div></div><span>›</span></div>`).join(''):`<div class="card empty">还没有记录</div>`}</div>`)}
function openRecordDetail(type,id){const key=type==='fill'?'fills':type==='usage'?'paperUsages':'tests';const x=db[key].find(v=>v.id===id);if(!x)return;const title=type==='fill'?'灌墨记录':type==='usage'?'用纸记录':'书写测试';let body=`<div class="card"><div class="name">${title}</div><div class="meta">${fmt(x.date)}</div>`;if(type==='fill')body+=`<div class="section-title">钢笔</div><div class="name">${esc(penName(x.penId))}</div><div class="section-title">墨水</div><div class="name">${esc(inkName(x.inkId))}</div><div class="meta">${x.ml||''} ml ${x.endDate?' · 结束于 '+fmt(x.endDate):' · 正在使用'}</div>`;if(type==='usage')body+=`<div class="section-title">纸张</div><div class="name">${esc(paperName(x.paperId))}</div><div class="meta">${x.qty||0} 张</div>`;if(type==='test')body+=`<div class="section-title">评价对象</div><div class="meta">${[x.penId&&penName(x.penId),x.inkId&&inkName(x.inkId),x.paperId&&paperName(x.paperId)].filter(Boolean).join(' · ')}</div><div class="section-title">评分</div><div class="stars">${'★'.repeat(+x.rating||0)}${'☆'.repeat(5-(+x.rating||0))}</div>${x.paperTags?.length?`<div class="section-title">纸表现</div>${x.paperTags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}`:''}${x.inkTags?.length?`<div class="section-title">墨表现</div>${x.inkTags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}`:''}${x.penTags?.length?`<div class="section-title">笔手感</div>${x.penTags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}`:''}${x.note?`<div class="section-title">备注</div><div>${esc(x.note)}</div>`:''}${x.review?`<div class="section-title">书写感受</div><div>${esc(x.review)}</div>`:''}`;body+=`</div><div class="actions"><button class="ghost" onclick="${type==='fill'?`openFill('')`:`${type==='usage'?`openUsageForm('${id}')`:`openTestForm('${id}')`}`}" >编辑</button><button class="ghost danger" onclick="removeItem('${type}','${id}')">删除</button></div>`;layout(`<button class="back" onclick="go('record')">‹ 返回记录</button><h2>${title}</h2>${body}`)}
function renderRecordChoiceModal(type,items){return''}
// 将“选择纸张”时的 value 改成可读名称；测试选择器使用隐藏 id。
function openRecordSelector(){ }
// 兼容简单的表单选择：在打开选择器后，直接写回隐藏字段。
function setUsageLabel(id){const el=document.getElementById('usagePaper');if(el){const p=db.papers.find(x=>x.id===id);el.value=p?paperName(id):id}}
// 覆盖 chooseValue 对测试多选/单选的行为
const _chooseValue=chooseValue;
chooseValue=function(type,value){
  closeModal();
  if(type==='brand'||type==='nib'||type==='nibMaterial'||type==='location'){const name=type==='nib'?'nib':type;const el=document.querySelector(`[name="${name}"]`);if(el)el.value=value;return}
  if(type==='paperForUsage'){setUsageLabel(value);return}
  if(type==='testPen'||type==='testInk'||type==='testPaper'){setTestChoice(type,value);return}
};
render();
